<script setup lang="ts">
const { t, localePath, locale, basePath } = useLocale()

import { Menu, Search, X } from 'lucide-vue-next'
import { fetchMediaGuides, useMediaGuides, type MediaGuide } from '~/composables/useMediaGuides'
import { resolveGuideTopic } from '~/shared/guide-localization'
import { takeMediaPreload } from '~/composables/useMediaPreload'
useSeoMeta({title:() => t('Panduan — Sudut Haramain'),description:() => t('Panduan praktis untuk memahami kehidupan, perjalanan, dan kebutuhan sehari-hari di Makkah dan Madinah.')})
const route=useRoute(),router=useRouter();const {guides,pending,error}=await useMediaGuides();const searchQuery=ref(''),isDrawerOpen=ref(false),topicTrigger=ref<HTMLButtonElement|null>(null),drawerCloseButton=ref<HTMLButtonElement|null>(null),contentPane=ref<HTMLElement|null>(null)
const grouped=computed(()=>{const q=searchQuery.value.trim().toLocaleLowerCase();return guides.value.reduce((groups,g)=>{if(q&&!`${g.title} ${g.summary||''}`.toLocaleLowerCase().includes(q))return groups;const existing=groups.find(x=>x.title===g.group);if(existing)existing.topics.push(g);else groups.push({title:g.group,topics:[g]});return groups},[] as Array<{title:string;topics:MediaGuide[]}>)});const all= computed(()=>guides.value);const activeSlug=ref('')
const otherLocale = locale.value === 'id' ? 'en' : 'id'
const alternateKey = 'guide-alternates-' + otherLocale
const { data: otherGuides } = await useAsyncData<MediaGuide[]>(alternateKey, async () => { const preload = takeMediaPreload<MediaGuide[]>(alternateKey); return preload.used ? preload.data || [] : fetchMediaGuides(otherLocale) }, { default: () => [] })
const contentLinks = useContentLocaleLinks()
const activeTopic=computed(()=>all.value.find(g=>g.slug===activeSlug.value)||all.value[0]||null);const activeGroup=computed(()=>activeTopic.value?.group||'')
watch([activeTopic, otherGuides], () => {
  const other = otherGuides.value.find(g => g.id === activeTopic.value?.id)
  contentLinks.value = {
    key: route.path,
    paths: { [locale.value]: localePath('/panduan') + (activeTopic.value ? '#' + activeTopic.value.slug : ''), ...(other ? { [otherLocale]: localePath('/panduan', otherLocale) + '#' + other.slug } : {}) },
    fallback: { [otherLocale]: localePath('/panduan?translation=unavailable', otherLocale) },
  }
}, { immediate: true })
const hydrated = ref(false)
const topicUnavailable = ref(false)
onMounted(() => { hydrated.value = true })
watch([()=>route.hash,all,otherGuides,hydrated],()=>{
  if (!hydrated.value) return
  const resolved = resolveGuideTopic(all.value, otherGuides.value, route.hash)
  activeSlug.value = resolved.topic?.slug || ''
  topicUnavailable.value = resolved.unavailable
  if (route.hash && !resolved.unavailable && resolved.topic && route.hash !== '#' + resolved.topic.slug) router.replace({ hash: '#' + resolved.topic.slug })
},{immediate:true})
function selectTopic(topic:MediaGuide){activeSlug.value=topic.slug;isDrawerOpen.value=false;router.push({path:localePath('/panduan'),hash:`#${topic.slug}`});nextTick(()=>contentPane.value?.scrollIntoView({behavior:'smooth',block:'start'}))}
function openDrawer(){isDrawerOpen.value=true;nextTick(()=>drawerCloseButton.value?.focus())}function closeDrawer(restore=true){isDrawerOpen.value=false;if(restore)nextTick(()=>topicTrigger.value?.focus())}function onKeydown(e:KeyboardEvent){if(e.key==='Escape'&&isDrawerOpen.value)closeDrawer()}onMounted(()=>window.addEventListener('keydown',onKeydown));onBeforeUnmount(()=>window.removeEventListener('keydown',onKeydown))
</script>
<template><div class="bg-sht-off-white pt-24 text-sht-charcoal sm:pt-28"><div class="mx-auto max-w-[84rem] px-5 sm:px-6 lg:px-8"><div class="flex items-center justify-between border-b border-sht-stone pb-5 lg:hidden"><div><p class="text-xs font-semibold uppercase tracking-[0.22em] text-sht-sage">{{ t('PANDUAN') }}</p><p class="mt-1 text-sm text-sht-charcoal/60">{{ t('Pusat informasi praktis') }}</p></div><button ref="topicTrigger" class="inline-flex min-h-[44px] items-center gap-2 rounded-full border border-sht-olive/25 px-4 text-sm font-semibold text-sht-olive-dark" @click="openDrawer"><Menu class="h-4 w-4"/>{{ t('Daftar Topik') }}</button></div><div class="grid lg:grid-cols-[300px_minmax(0,1fr)] lg:gap-16"><aside class="hidden lg:block"><div class="sticky top-24 max-h-[calc(100vh-7rem)] overflow-y-auto pb-8 pr-4"><div class="border-b border-sht-stone pb-5"><p class="text-xs font-semibold uppercase tracking-[0.22em] text-sht-sage">{{ t('PANDUAN') }}</p><p class="mt-2 text-sm leading-relaxed text-sht-charcoal/60">{{ t('Pusat informasi praktis Sudut Haramain.') }}</p><label class="relative mt-5 block"><Search class="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-sht-sage"/><input v-model="searchQuery" type="search" :placeholder="t('Cari topik panduan...')" class="min-h-[44px] w-full rounded-xl border border-sht-stone bg-white pl-10 pr-3 text-sm"/></label></div><nav class="pt-5"><div v-for="group in grouped" :key="group.title" class="mb-6"><h2 class="px-3 text-[0.68rem] font-semibold uppercase tracking-[0.18em] text-sht-charcoal/55">{{t(group.title)}}</h2><div class="mt-2 ml-3.5"><button v-for="topic in group.topics" :key="topic.slug" class="relative flex min-h-[35px] w-full items-center rounded-lg px-3 text-left text-sm" :class="activeTopic?.slug===topic.slug?'bg-sht-olive/8 font-semibold text-sht-olive-dark before:absolute before:inset-y-2 before:left-0 before:w-0.5 before:bg-sht-gold':'text-sht-charcoal/75'" @click="selectTopic(topic)">{{topic.title}}</button></div></div><p v-if="!grouped.length&&!pending" class="px-3 py-4 text-sm text-sht-charcoal/60">{{ t('Topik belum ditemukan.') }}</p></nav></div></aside><main ref="contentPane" class="min-w-0 pt-10 pb-20 lg:pt-12 lg:pb-32" aria-live="polite"><p v-if="topicUnavailable" role="status" class="mb-6 rounded-xl bg-sht-gold/15 p-4 text-sm">{{ t('Konten dalam bahasa ini belum tersedia.') }} {{ t('Daftar konten yang tersedia ditampilkan di bawah ini.') }}</p><div v-if="pending" class="max-w-[820px] py-16 text-sm text-sht-charcoal/60">{{ t('Memuat panduan...') }}</div><div v-else-if="error||!activeTopic" class="max-w-[820px] py-16 text-sm text-sht-charcoal/60">{{ t(error ? 'Panduan belum dapat dimuat. Silakan coba lagi nanti.' : 'Konten dalam bahasa ini belum tersedia.') }}<NuxtLink v-if="locale === 'en'" :to="localePath('/panduan','id')" class="mt-4 block underline">{{ t('Buka versi Indonesia') }}</NuxtLink></div><div v-else class="max-w-[820px]"><p class="text-xs font-semibold uppercase tracking-[0.22em] text-sht-sage">{{t(activeGroup)}}</p><h1 class="mt-4 font-hero text-4xl font-bold leading-tight text-sht-olive-dark sm:text-5xl">{{activeTopic.title}}</h1><p v-if="activeTopic.summary" class="mt-5 max-w-3xl text-base leading-relaxed text-sht-charcoal/70 sm:text-lg">{{activeTopic.summary}}</p><div v-if="activeTopic.body.length" class="mt-10"><template v-for="(block,i) in activeTopic.body" :key="i"><p v-if="block.type==='paragraph'" class="mb-6 text-base leading-[1.85] text-sht-charcoal/80">{{block.text}}</p><h2 v-else-if="block.type==='heading'&&block.level===2" class="mb-4 mt-12 font-hero text-3xl font-bold text-sht-olive-dark">{{block.text}}</h2><h3 v-else-if="block.type==='heading'" class="mb-3 mt-8 font-hero text-2xl font-bold text-sht-olive-dark">{{block.text}}</h3><ul v-else-if="block.type==='list'&&!block.ordered" class="mb-6 list-disc space-y-2 pl-6 text-base leading-relaxed"><li v-for="item in block.items" :key="item">{{item}}</li></ul><ol v-else-if="block.type==='list'" class="mb-6 list-decimal space-y-2 pl-6 text-base leading-relaxed"><li v-for="item in block.items" :key="item">{{item}}</li></ol><blockquote v-else-if="block.type==='blockquote'" class="mb-8 border-l-2 border-sht-gold pl-5 font-hero text-2xl leading-relaxed text-sht-olive-dark">{{block.text}}</blockquote><figure v-else-if="block.type==='image'" class="mb-8"><img :src="block.src" :alt="block.alt||activeTopic.title" class="w-full rounded-xl object-cover"/><figcaption v-if="block.caption" class="mt-2 text-xs text-sht-charcoal/50">{{block.caption}}</figcaption></figure><aside v-else-if="block.type==='callout'" class="mb-8 border-l-2 border-sht-gold bg-sht-gold/10 px-5 py-4 text-sm leading-relaxed">{{block.text}}</aside></template></div><div v-else class="mt-10 border-t border-sht-stone pt-7 text-sm text-sht-charcoal/60">{{ t('Konten panduan belum tersedia.') }}</div></div></main></div></div><Teleport to="body"><div v-if="isDrawerOpen" class="fixed inset-0 z-[70] bg-sht-olive-dark/45 lg:hidden" @click.self="closeDrawer()"><aside class="flex h-full w-[90vw] max-w-[360px] flex-col bg-sht-off-white" role="dialog" aria-modal="true"><div class="flex items-center justify-between border-b border-sht-stone px-5 py-4"><p class="text-xs font-semibold uppercase tracking-[0.22em] text-sht-sage">{{ t('DAFTAR TOPIK') }}</p><button :aria-label="t('Tutup daftar topik')" ref="drawerCloseButton" class="h-11 w-11 rounded-full" @click="closeDrawer()"><X/></button></div><div class="border-b border-sht-stone px-5 py-4"><input v-model="searchQuery" type="search" :placeholder="t('Cari topik panduan...')" class="min-h-[44px] w-full rounded-xl border border-sht-stone bg-white px-3 text-sm"/></div><nav class="min-h-0 flex-1 overflow-y-auto px-5 py-5"><div v-for="group in grouped" :key="group.title" class="mb-6"><h2 class="px-3 text-[0.68em] font-semibold uppercase tracking-[0.18em] text-sht-charcoal/55">{{t(group.title)}}</h2><button v-for="topic in group.topics" :key="topic.slug" class="flex min-h-[42px] w-full items-center rounded-lg px-3 text-left text-sm" :class="activeTopic?.slug===topic.slug?'bg-sht-olive/8 font-semibold':''" @click="selectTopic(topic)">{{topic.title}}</button></div></nav></aside></div></Teleport></div></template>
